"""Generate the local-only, exhaustive pack effect reference; no game text published."""
import hashlib
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PACK = ROOT / 'packs/kss16'
OUT = ROOT / 'references/recovery/EFFECTS-REFERENCE.md'


def load(name):
    return json.loads((PACK / name).read_text(encoding='utf-8'))


def compact(value):
    return json.dumps(value, ensure_ascii=False, separators=(', ', ': '))


def main():
    lines = ['# Complete local pack effects reference', '',
        'Generated by `tools/build_effect_reference.py`. Local use only.', '',
        'Scope: every item, trait, story event and imported system event in the active pack. '
        'Other-story source archives are not playable content in this project.', '',
        'Read `docs/EFFECTS-REFERENCE.md` for engine semantics, unresolved behavior and '
        'proposed prototype rules. Catalog descriptions state intent; structured effects '
        'and the engine determine current behavior. Event nodes below preserve branching '
        'and conditions: listed effects are possible outcomes, not cumulative guaranteed rewards.', '',
        '## Input fingerprints', '']
    for path in sorted(PACK.rglob('*.json')):
        lines.append(f'- `{path.relative_to(PACK)}`: `{hashlib.sha256(path.read_bytes()).hexdigest()}`')
    counts = {}
    for filename, key, effect_key, description in [
        ('items.json', 'items', 'effects', 'effectText'),
        ('traits.json', 'traits', 'effectList', 'description'),
    ]:
        rows = load(filename)[key]
        counts[key] = len(rows)
        lines += ['', f'## {key.title()} ({len(rows)})', '']
        for row in sorted(rows, key=lambda r: r['id']):
            lines += [f"### {row['id']} — {row.get('name', '')}", '',
                row.get(description, '') or 'No catalog effect description.', '']
            if key == 'traits':
                lines += [f"Setup candidate: {row.get('gachable') is True}; "
                    f"story: {row.get('storyId', 'global')}; tier: {row.get('rank')}; "
                    f"polarity: {row.get('type')}; lifetime: {row.get('initialLifeTime', 'permanent')}.", '']
            mechanics = {k: v for k, v in row.items() if k in
                [effect_key, 'type', 'locationIdList', 'locationType', 'conditions', 'duration', 'isConsumable']}
            lines += ['```json', json.dumps(mechanics, ensure_ascii=False, indent=2), '```', '']
            if not row.get(effect_key):
                lines += ['No structured effect: do not infer a working mechanic from the description.', '']
    source = (ROOT / 'lib/engine/effects.dart').read_text(encoding='utf-8')
    noops = set(re.findall(r"'([A-Z_0-9]+)':\s*\(s, a, e\)\s*\{\s*\}", source))
    event_count = 0
    for filename in ['events/events.json', 'events/system.json']:
        data = load(filename)
        nodes = {n['id']: n for n in data.get('nodes', [])}
        boxes = {}
        for node in nodes.values():
            boxes.setdefault(node.get('boxId'), []).append(node['id'])
        lines += ['', f'## Events from {filename}', '']
        for event in data.get('events', []):
            event_count += 1
            lines += [f"### Event {event['id']} — {event.get('name', '')}", '',
                'Eligibility and metadata:', '```json', json.dumps(event, ensure_ascii=False, indent=2), '```', '']
            pending = [event.get('rootNodeId')]
            seen = set()
            while pending:
                node_id = pending.pop()
                if node_id in seen or node_id not in nodes:
                    continue
                seen.add(node_id)
                node = nodes[node_id]
                for key in ['nextNodeId', 'nextNodeIdIfTrue', 'nextNodeIdIfFalse']:
                    pending.append(node.get(key))
                for option in node.get('options') or []:
                    pending.append(option.get('nextNodeId'))
                    box = option.get('nextBoxId')
                    if option.get('nextNodeId') is None and box is not None:
                        pending.extend(boxes.get(box, [])[:1])
                # Preserve conditions, effects, choices and prose together, but omit art/audio payload.
                details = {k: v for k, v in node.items() if k in [
                    'id', 'type', 'boxId', 'text', 'elseText', 'optionText', 'changer',
                    'changers', 'conditionSet', 'conditions', 'options', 'nextNodeId',
                    'nextNodeIdIfTrue', 'nextNodeIdIfFalse']}
                if details:
                    lines += [f'Node `{node_id}`:', '```json', json.dumps(details, ensure_ascii=False, indent=2), '```', '']
                for verb in sorted(noops):
                    if verb in compact(details):
                        lines += [f'**Current no-op:** `{verb}`. Original behavior unresolved; see proposed rules.', '']
            lines += [f'Reachable nodes documented: {len(seen)}.', '']
    counts['events'] = event_count
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text('\n'.join(lines) + '\n', encoding='utf-8')
    print(f'{OUT}: {counts}')


if __name__ == '__main__':
    main()
